# CUDA implementation (kernel + launcher)
# ----------------------------------------------------------------------
cpp_source = r'''
#include <torch/extension.h>

// Declaration of the launcher (defined in the CUDA source)
void rms_norm_forward(torch::Tensor input, torch::Tensor output, float eps);
'''

cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

template<int TPB>
__global__ void rms_norm_kernel(const half* __restrict__ input,
                                half* __restrict__ output,
                                int B, int C, int S, float eps) {
    // Each block handles one (batch, spatial) pair
    int idx = blockIdx.x;               // 0 .. B*S-1
    int s   = idx % S;                  // spatial index
    int b   = idx / S;                  // batch index

    int tid = threadIdx.x;              // feature index within the block
    const int stride = S;               // distance between consecutive feature elements

    // ------------------------------------------------------------------
    // 1) Compute sum of squares for this (b, s) across the feature dim
    // ------------------------------------------------------------------
    __shared__ float shmem[TPB];
    float val = 0.0f;
    if (tid < C) {
        // offset = ((b * C + tid) * S) + s
        int offset = ((b * C + tid) * S) + s;
        half h = input[offset];
        float f = __half2float(h);
        val = f * f;
    }
    shmem[tid] = val;
    __syncthreads();

    // reduction in shared memory (binary tree)
    for (int offset = TPB / 2; offset > 0; offset >>= 1) {
        if (tid < offset) {
            shmem[tid] += shmem[tid + offset];
        }
        __syncthreads();
    }

    // ------------------------------------------------------------------
    // 2) Compute RMS and its reciprocal (broadcast to whole warp)
    // ------------------------------------------------------------------
    float rms = 0.0f;
    if (tid == 0) {
        float mean = shmem[0] / static_cast<float>(C);
        rms = sqrtf(mean + eps);
    }
    // broadcast rms to all threads in the block
    rms = __shfl_sync(0xffffffff, rms, 0);
    float inv_rms = 1.0f / rms;
    __syncthreads();

    // ------------------------------------------------------------------
    // 3) Normalize and write output
    // ------------------------------------------------------------------
    if (tid < C) {
        int offset = ((b * C + tid) * S) + s;
        half h = input[offset];
        float f = __half2float(h);
        float out_f = f * inv_rms;
        output[offset] = __float2half(out_f);
    }
}

// Launcher ---------------------------------------------------------------
void rms_norm_forward(torch::Tensor input, torch::Tensor output, float eps) {
    const int B = input.size(0);
    const int C = input.size(1);
    const int64_t total = input.numel();          // B * C * S
    const int S = static_cast<int>(total / (static_cast<int64_t>(B) * C));

    const int threads = 256;                      // TPB
    const int blocks  = B * S;                    // one block per (batch, spatial) pair

    rms_norm_kernel<256><<<blocks, threads>>>(
        reinterpret_cast<const half*>(input.data_ptr()),
        reinterpret_cast<half*>(output.data_ptr()),
        B, C, S, eps
    );

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("[rms_norm_forward] CUDA error: %s\\n", cudaGetErrorString(err));
    }
}
'''

# Compile the extension (the harness will supply the appropriate C++ standard)
_ext = load_inline(
    name="rmsnorm_cuda",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["rms_norm_forward"],
    verbose=False,
)

# ----------------------------------------------------------------------
# PyTorch module that uses the custom kernel
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    RMS Normalization implemented with a custom CUDA kernel.
    Mirrors the reference Model but runs entirely on fp16 data.
    """
    def __init__(self, num_features: int, eps: float = 1e-5):
        super().__init__()
        self.num_features = num_features
        self.eps = eps

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure fp16, contiguous layout
        if x.dtype != torch.float16:
            x = x.to(torch.float16)
        x = x.contiguous()
        out = torch.empty_like(x)
        _ext.rms_norm_forward(x, out, self.eps)
        return out

# ----------------------------------------------------------------------
# Helper functions matching the original benchmarking harness
# ----------------------------------------------------------------------
def get_inputs():
    batch_size = 112
    features   = 64
    dim1 = 512
    dim2 = 512
    x = torch.rand(batch_size, features, dim1, dim2, dtype=torch.float16, device='cuda')
    return [x]

def get_init_inputs():
    return [64]   # num_features
